window.BlessData.files["Tests-BlessProvidersTests"] = {"group":"Tests-BlessProvidersTests","files":[{"path":"Tests/BlessProvidersTests/OpenAICompatibleProviderTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,120]],"header":{"lines":[1,10],"target":"BlessProvidersTests","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":428,"scopes":[["S","OpenAICompatibleProviderTests",null,"",17,18,[18,37],120,null,-1,0,"a"],["f","complete",[],"",21,22,[22,33],34,null,0,0,"a"],["f","httpError",[],"",36,37,[37,34],44,null,0,0,"a"],["f","missingKey",[],"",46,47,[47,35],53,null,0,0,"a"],["f","stream",[],"",55,56,[56,31],77,null,0,0,"a"],["f","models",[],"",79,80,[80,31],85,null,0,0,"a"],["f","presets",[],"",87,88,[88,19],95,null,0,0,"a"],["f","blessedClient",[],"",97,98,[98,38],119,null,0,0,"a"]],"old":"","new":"//\n//  OpenAICompatibleProviderTests.swift\n//  BlessProvidersTests\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The client against a stubbed server: where it posts, what it sends, how it reads a\n//        whole reply and a stream, and what an HTTP error carries. Serialized: the stub is shared.\n//\n\nimport Bless\nimport Foundation\nimport Testing\n@testable import BlessProviders\n\n@Suite(\"OpenAI-compatible provider\", .serialized)\nstruct OpenAICompatibleProviderTests {\n    let request = ChatRequest(model: \"mistral-small-latest\", messages: [.user(\"How should I take it?\")])\n\n    @Test(\"complete posts to the preset's URL with the bearer key and returns the message\")\n    func complete() async throws {\n        let body = #\"{\"id\":\"cmpl-9\",\"model\":\"mistral-small-2506\",\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"With food.\"},\"finish_reason\":\"stop\"}]}\"#\n        let session = StubProtocol.session(answering: .init(status: 200, body: Data(body.utf8)))\n        let provider = OpenAICompatibleProvider(preset: .mistral, apiKey: \"test-key\", session: session)\n        let response = try await provider.complete(request)\n        #expect(response.message.content == \"With food.\")\n        #expect(response.id == \"cmpl-9\")\n        let sent = try #require(StubProtocol.lastRequest)\n        #expect(sent.url?.absoluteString == \"https://api.mistral.ai/v1/chat/completions\")\n        #expect(sent.httpMethod == \"POST\")\n        #expect(sent.value(forHTTPHeaderField: \"Authorization\") == \"Bearer test-key\")\n        #expect(StubProtocol.lastBody[\"stream\"] as? Bool == false)\n    }\n\n    @Test(\"an HTTP error throws its status and the start of its body\")\n    func httpError() async throws {\n        let session = StubProtocol.session(answering: .init(status: 401, body: Data(#\"{\"message\":\"Unauthorized\"}\"#.utf8)))\n        let provider = OpenAICompatibleProvider(preset: .mistral, apiKey: \"bad\", session: session)\n        await #expect(throws: ProviderError.http(status: 401, body: #\"{\"message\":\"Unauthorized\"}\"#)) { try await provider.complete(request) }\n        await #expect(throws: ProviderError.http(status: 401, body: #\"{\"message\":\"Unauthorized\"}\"#)) {\n            for try await _ in provider.stream(request) {}\n        }\n    }\n\n    @Test(\"a missing key is refused before any request when the preset needs one\")\n    func missingKey() async throws {\n        let session = StubProtocol.session(answering: .init(status: 200, body: Data()))\n        await #expect(throws: ProviderError.missingAPIKey) {\n            try await OpenAICompatibleProvider(preset: .mistral, apiKey: nil, session: session).complete(request)\n        }\n        #expect(StubProtocol.lastRequest == nil)\n    }\n\n    @Test(\"stream yields deltas from an SSE body until [DONE]\")\n    func stream() async throws {\n        let sse = \"\"\"\n        data: {\"id\":\"c-1\",\"model\":\"m\",\"choices\":[{\"delta\":{\"role\":\"assistant\",\"content\":\"With \"}}]}\n\n        : comment\n\n        data: {\"id\":\"c-1\",\"model\":\"m\",\"choices\":[{\"delta\":{\"content\":\"food.\"},\"finish_reason\":\"stop\"}]}\n\n        data: [DONE]\n\n        data: {\"choices\":[{\"delta\":{\"content\":\"never read\"}}]}\n\n        \"\"\"\n        let session = StubProtocol.session(answering: .init(status: 200, body: Data(sse.utf8), contentType: \"text/event-stream\"))\n        let provider = OpenAICompatibleProvider(preset: .mistral, apiKey: \"k\", session: session)\n        let assembled = try await provider.stream(request).assembled(model: \"fallback\")\n        #expect(assembled.message.content == \"With food.\")\n        #expect(assembled.finishReason == .stop)\n        #expect(assembled.id == \"c-1\")\n        #expect(StubProtocol.lastBody[\"stream\"] as? Bool == true)\n        #expect(StubProtocol.lastRequest?.value(forHTTPHeaderField: \"Accept\") == \"text/event-stream\")\n    }\n\n    @Test(\"models lists the ids the key can use\")\n    func models() async throws {\n        let session = StubProtocol.session(answering: .init(status: 200, body: Data(#\"{\"object\":\"list\",\"data\":[{\"id\":\"mistral-small-latest\"},{\"id\":\"mistral-large-latest\"}]}\"#.utf8)))\n        let ids = try await OpenAICompatibleProvider(preset: .mistral, apiKey: \"k\", session: session).models()\n        #expect(ids == [\"mistral-small-latest\", \"mistral-large-latest\"])\n        #expect(StubProtocol.lastRequest?.url?.absoluteString == \"https://api.mistral.ai/v1/models\")\n    }\n\n    @Test(\"the presets name their endpoints; Sewn's carries its required object and needs no key\")\n    func presets() {\n        #expect(Preset.openAI.completionsURL.absoluteString == \"https://api.openai.com/v1/chat/completions\")\n        #expect(Preset.mistral.modelsURL.absoluteString == \"https://api.mistral.ai/v1/models\")\n        let sewn = Preset.sewn(sewn: [\"owner_id\": \"ada\"])\n        #expect(sewn.completionsURL.absoluteString == \"http://127.0.0.1:47080/v1/chat/completions\")\n        #expect(!sewn.requiresKey)\n        #expect(sewn.extra[\"sewn\"] == [\"owner_id\": \"ada\"])\n    }\n\n    @Test(\"Blessed wraps the real client exactly as it wraps any provider\")\n    func blessedClient() async throws {\n        let body = #\"{\"id\":\"cmpl-9\",\"model\":\"m\",\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"With food.\"},\"finish_reason\":\"stop\"}]}\"#\n        let session = StubProtocol.session(answering: .init(status: 200, body: Data(body.utf8)))\n        let doctor = ReviewerIdentity(id: \"dr-1\", displayName: \"Dr. One\")\n        let gate = Gate()\n        let blessed = Blessed(upstream: OpenAICompatibleProvider(preset: .mistral, apiKey: \"k\", session: session), gate: gate) { _ in\n            Routing(conversationID: \"v-1\", recipient: Party(id: \"ada\", displayName: \"Ada\"), reviewers: [doctor.party])\n        }\n        let reviewer = Task {\n            for _ in 0..<5000 {\n                if let petition = try await gate.pending().first {\n                    try await gate.decide(petition.id, .amend(content: \"With food, twice a day.\"), as: doctor)\n                    return\n                }\n                try await Task.sleep(for: .milliseconds(1))\n            }\n        }\n        let response = try await blessed.complete(request)\n        try await reviewer.value\n        #expect(response.message.content == \"With food, twice a day.\")\n        #expect(blessed.name == \"blessed(mistral)\")\n    }\n}\n"},{"path":"Tests/BlessProvidersTests/SSETests.swift","status":"added","lang":"swift","hunks":[[1,0,1,42]],"header":{"lines":[1,10],"target":"BlessProvidersTests","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":436,"scopes":[["S","SSETests",null,"",16,17,[17,16],42,null,-1,0,"a"],["f","events",["_"],"",18,18,[18,44],26,null,0,0,"a"],["f","split",[],"",28,29,[29,17],31,null,0,0,"a"],["f","multiline",[],"",33,34,[34,21],36,null,0,0,"a"],["f","crlf",[],"",38,39,[39,16],41,null,0,0,"a"]],"old":"","new":"//\n//  SSETests.swift\n//  BlessProvidersTests\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Server-sent events read byte by byte: blank lines end events, comments and other\n//        fields are skipped, CRLF reads as LF, multi-line data joins with newlines.\n//\n\nimport Foundation\nimport Testing\n@testable import BlessProviders\n\n@Suite(\"Server-sent events\")\nstruct SSETests {\n    func events(_ text: String) -> [String] {\n        var parser = SSEParser()\n        var out: [String] = []\n        for byte in Array(text.utf8) {\n            if let event = parser.feed(byte) { out.append(event) }\n        }\n        if let event = parser.finish() { out.append(event) }\n        return out\n    }\n\n    @Test(\"events split on blank lines; comments and other fields are ignored\")\n    func split() {\n        #expect(events(\": keep-alive\\ndata: {\\\"a\\\":1}\\n\\nevent: x\\nid: 7\\ndata: [DONE]\\n\\n\") == [\"{\\\"a\\\":1}\", \"[DONE]\"])\n    }\n\n    @Test(\"multi-line data joins with a newline; a space after the colon is optional\")\n    func multiline() {\n        #expect(events(\"data: one\\ndata:two\\n\\n\") == [\"one\\ntwo\"])\n    }\n\n    @Test(\"CRLF line endings read as LF, and an event open at the end is delivered\")\n    func crlf() {\n        #expect(events(\"data: a\\r\\n\\r\\ndata: b\") == [\"a\", \"b\"])\n    }\n}\n"},{"path":"Tests/BlessProvidersTests/Stub.swift","status":"added","lang":"swift","hunks":[[1,0,1,68]],"header":{"lines":[1,10],"target":"BlessProvidersTests","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":441,"scopes":[["C","StubProtocol",null,"final",15,15,[15,59],68,null,-1,0,"a"],["S","Reply",null,"",16,16,[16,27],20,null,0,0,"a"],["f","session",["answering"],"static",25,25,[25,62],31,null,0,0,"a"],["v","lastRequest",null,"static",33,33,[33,40],33,null,0,8,"a"],["v","lastBody",null,"static",35,35,[35,39],39,null,0,0,"a"],["f","canInit",["with"],"override class",41,41,[41,66],41,null,0,8,"a"],["f","canonicalRequest",["for"],"override class",42,42,[42,80],42,null,0,8,"a"],["f","startLoading",[],"override",44,44,[44,33],65,null,0,0,"a"],["f","stopLoading",[],"override",67,67,[67,32],67,null,0,8,"a"]],"old":"","new":"//\n//  Stub.swift\n//  BlessProvidersTests\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A URLProtocol that answers the provider's requests from the test, on an ephemeral\n//        session, and keeps each request (body included) for the test to read. No network.\n//\n\nimport Foundation\nimport Synchronization\n\nfinal class StubProtocol: URLProtocol, @unchecked Sendable {\n    struct Reply: Sendable {\n        var status: Int\n        var body: Data\n        var contentType = \"application/json\"\n    }\n\n    static let reply = Mutex<Reply>(Reply(status: 200, body: Data()))\n    static let seen = Mutex<[URLRequest]>([])\n\n    static func session(answering reply: Reply) -> URLSession {\n        self.reply.withLock { $0 = reply }\n        seen.withLock { $0.removeAll() }\n        let configuration = URLSessionConfiguration.ephemeral\n        configuration.protocolClasses = [StubProtocol.self]\n        return URLSession(configuration: configuration)\n    }\n\n    static var lastRequest: URLRequest? { seen.withLock { $0.last } }\n\n    static var lastBody: [String: Any] {\n        guard let body = lastRequest?.httpBody,\n              let object = try? JSONSerialization.jsonObject(with: body) as? [String: Any] else { return [:] }\n        return object\n    }\n\n    override class func canInit(with request: URLRequest) -> Bool { true }\n    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }\n\n    override func startLoading() {\n        var request = self.request\n        if request.httpBody == nil, let stream = request.httpBodyStream {\n            stream.open()\n            var data = Data()\n            var buffer = [UInt8](repeating: 0, count: 4096)\n            while stream.hasBytesAvailable {\n                let count = stream.read(&buffer, maxLength: buffer.count)\n                if count <= 0 { break }\n                data.append(buffer, count: count)\n            }\n            stream.close()\n            request.httpBody = data\n        }\n        Self.seen.withLock { $0.append(request) }\n        let reply = Self.reply.withLock { $0 }\n        let response = HTTPURLResponse(url: request.url!, statusCode: reply.status, httpVersion: \"HTTP/1.1\",\n                                       headerFields: [\"Content-Type\": reply.contentType])!\n        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)\n        client?.urlProtocol(self, didLoad: reply.body)\n        client?.urlProtocolDidFinishLoading(self)\n    }\n\n    override func stopLoading() {}\n}\n"},{"path":"Tests/BlessProvidersTests/WireTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,81]],"header":{"lines":[1,10],"target":"BlessProvidersTests","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":450,"scopes":[["S","WireTests",null,"",17,18,[18,17],81,null,-1,0,"a"],["f","encoded",["_"],"",19,19,[19,66],22,null,0,0,"a"],["f","request",[],"",24,25,[25,26],36,null,0,0,"a"],["f","extraPrecedence",[],"",38,39,[39,34],47,null,0,0,"a"],["f","response",[],"",49,50,[50,27],59,null,0,0,"a"],["f","parts",[],"",61,62,[62,24],67,null,0,0,"a"],["f","chunk",[],"",69,70,[70,24],74,null,0,0,"a"],["f","noChoices",[],"",76,77,[77,28],80,null,0,0,"a"]],"old":"","new":"//\n//  WireTests.swift\n//  BlessProvidersTests\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The chat-completions wire: requests in OpenAI's shape with extra fields at the top\n//        level, responses and stream chunks read into Bless's neutral types.\n//\n\nimport Bless\nimport Foundation\nimport Testing\n@testable import BlessProviders\n\n@Suite(\"Wire\")\nstruct WireTests {\n    func encoded(_ request: Wire.Request) throws -> [String: Any] {\n        let data = try JSONEncoder().encode(request)\n        return try #require(try JSONSerialization.jsonObject(with: data) as? [String: Any])\n    }\n\n    @Test(\"a request encodes to OpenAI's shape with snake_case keys and extra fields at the top level\")\n    func request() throws {\n        let chat = ChatRequest(model: \"mistral-small-latest\", messages: [.system(\"Be brief.\"), .user(\"Hi\")], temperature: 0.2,\n                               maxTokens: 300, extra: [\"safe_prompt\": true])\n        let json = try encoded(Wire.request(chat, preset: .mistral, stream: true))\n        #expect(json[\"model\"] as? String == \"mistral-small-latest\")\n        #expect(json[\"max_tokens\"] as? Int == 300)\n        #expect(json[\"stream\"] as? Bool == true)\n        #expect(json[\"safe_prompt\"] as? Bool == true)\n        let messages = try #require(json[\"messages\"] as? [[String: Any]])\n        #expect(messages.map { $0[\"role\"] as? String } == [\"system\", \"user\"])\n        #expect(messages.map { $0[\"content\"] as? String } == [\"Be brief.\", \"Hi\"])\n    }\n\n    @Test(\"a request's own extra wins over the preset's, and never over a standard field\")\n    func extraPrecedence() throws {\n        let preset = Preset.sewn(sewn: [\"owner_id\": \"ada\", \"scope\": \"visit\"])\n        let chat = ChatRequest(model: \"local\", messages: [.user(\"Hi\")], extra: [\"sewn\": [\"owner_id\": \"bea\"], \"model\": \"evil\"])\n        let json = try encoded(Wire.request(chat, preset: preset, stream: false))\n        #expect((json[\"sewn\"] as? [String: Any])?[\"owner_id\"] as? String == \"bea\")\n        #expect(json[\"model\"] as? String == \"local\")\n        let plain = try encoded(Wire.request(ChatRequest(model: \"local\", messages: [.user(\"Hi\")]), preset: preset, stream: false))\n        #expect((plain[\"sewn\"] as? [String: Any])?[\"scope\"] as? String == \"visit\")\n    }\n\n    @Test(\"a response decodes to a ChatResponse; an unknown finish reason reads as other\")\n    func response() throws {\n        let body = #\"{\"id\":\"cmpl-1\",\"model\":\"mistral-small-2506\",\"created\":1760961600,\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"Rest.\",\"refusal\":null},\"finish_reason\":\"model_length\"}],\"usage\":{\"prompt_tokens\":12,\"completion_tokens\":2,\"total_tokens\":14}}\"#\n        let response = try Wire.response(try JSONDecoder().decode(Wire.Response.self, from: Data(body.utf8)), model: \"fallback\")\n        #expect(response.id == \"cmpl-1\")\n        #expect(response.model == \"mistral-small-2506\")\n        #expect(response.message == .assistant(\"Rest.\"))\n        #expect(response.finishReason == .other)\n        #expect(response.usage == .init(promptTokens: 12, completionTokens: 2, totalTokens: 14))\n        #expect(response.created == Date(timeIntervalSince1970: 1_760_961_600))\n    }\n\n    @Test(\"content given as typed parts is read from its text parts\")\n    func parts() throws {\n        let body = #\"{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":[{\"type\":\"thinking\",\"thinking\":[]},{\"type\":\"text\",\"text\":\"Rest \"},{\"type\":\"text\",\"text\":\"well.\"}]},\"finish_reason\":\"stop\"}]}\"#\n        let response = try Wire.response(try JSONDecoder().decode(Wire.Response.self, from: Data(body.utf8)), model: \"m\")\n        #expect(response.message.content == \"Rest well.\")\n        #expect(response.model == \"m\")\n    }\n\n    @Test(\"a stream chunk decodes to a delta\")\n    func chunk() throws {\n        let body = #\"{\"id\":\"c-1\",\"model\":\"m\",\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"Re\"},\"finish_reason\":null}]}\"#\n        let delta = Wire.delta(try JSONDecoder().decode(Wire.Response.self, from: Data(body.utf8)))\n        #expect(delta == ChatDelta(role: .assistant, content: \"Re\", id: \"c-1\", model: \"m\"))\n    }\n\n    @Test(\"no choices is an error\")\n    func noChoices() throws {\n        let wire = try JSONDecoder().decode(Wire.Response.self, from: Data(#\"{\"choices\":[]}\"#.utf8))\n        #expect(throws: ProviderError.noChoices) { try Wire.response(wire, model: \"m\") }\n    }\n}\n"}]};
